    virtual ~CSWGuiInGameInventory();
    virtual void Draw(float f);
    virtual void HandleInputEvent(int type, int val);
    virtual void OnPanelAdded();
    virtual void OnPanelRemoved();
    // </VTABLE-GEN>
    CSWGuiInGameInventory(CSWGuiManager* pGuiManager);

    // CGuiInGame::m_nInventoryFilter, the item filter CheckFilter applies. 0-5 are KOTOR 1's cycle
