#if KOTOR1
    CSWGuiLabel   m_labelDescription;
    CSWGuiLabel   m_labelInv;
    CSWGuiLabel   m_labelCredits;
    CSWGuiLabel   m_labelCreditsValue;
    CSWGuiListBox m_lbItems;
    CSWGuiListBox m_lbDescription;
    CSWGuiLabel   m_labelBgPort;
    CSWGuiLabel   m_labelBgStats;
    CSWGuiLabel   m_labelPort;
    CSWGuiLabel   m_labelVit;
    CSWGuiLabel   m_labelDef;
    CSWGuiButton  m_btnExit;
    CSWGuiButton  m_btnUseItem;
    CSWGuiButton  m_btnQuestItems;
    CSWGuiButton  m_btnChange1;
    CSWGuiButton  m_btnChange2;
    CSWGuiButton  m_btnCharLeft;
    CSWGuiButton  m_btnCharRight;
    CInventoryLists    m_lists;
    unsigned long long m_oidSelected;
    short              m_nSavedTopRow;
    short              m_nSavedSelectedIndex;
    signed char        m_nNPC;
    unsigned char m_bRebuildItemList : 1;
    unsigned char m_bRestoreListPosition     : 1;
    unsigned char m_bSelectedItemUsable     : 1;
    unsigned char m_nReserved1       : 5;
    IosFloatingButtonIcon m_iconChange;
#else
    CSWGuiLabel   m_labelDescription;
    CSWGuiLabel   m_labelInv;
    CSWGuiLabel   m_labelCredits;
    CSWGuiLabel   m_labelCreditsValue;
    CSWGuiListBox m_lbItems;
    CSWGuiListBox m_lbDescription;
    CSWGuiButton  m_btnExit;
    CSWGuiButton  m_btnUseItem;
    CSWGuiLabel   m_aLabelBar[6];
    CSWGuiLabel   m_labelFilter;
    CSWGuiButton  m_btnAll;
    CSWGuiButton  m_btnDatapads;
    CSWGuiButton  m_btnWeapons;
    CSWGuiButton  m_btnArmor;
    CSWGuiButton  m_btnUseable;
    CSWGuiButton  m_btnQuests;
    CSWGuiButton  m_btnMisc;
    CInventoryLists                       m_lists;
    unsigned long long                    m_oidSelected;
    short                                 m_nSavedTopRow;
    short                                 m_nSavedSelectedIndex;
    unsigned char m_bRestoreListPosition   : 1;
    unsigned char m_bSelectedItemUsable   : 1;
    unsigned char m_bRebuildItemList : 1;
    unsigned char m_nReserved1     : 5;
    char          m_aReserved1[3];
#endif
